import datetime,hashlib,json
def append_event(connection,record):
    keys={"host","boot","event_id","trace","wall_at","mono_ns","received_at","action"}
    if set(record)!=keys or not all(isinstance(record[k],str) and record[k] for k in keys-{"mono_ns"}) or not isinstance(record["mono_ns"],int) or isinstance(record["mono_ns"],bool) or record["mono_ns"]<0:raise ValueError("invalid audit record")
    for key in ["wall_at","received_at"]:
        if datetime.datetime.fromisoformat(record[key]).utcoffset() is None:raise ValueError("timezone required")
    original={k:v for k,v in record.items() if k!="received_at"}
    digest=hashlib.sha256(json.dumps(original,sort_keys=True,separators=(",",":"),ensure_ascii=False).encode()).hexdigest()
    with connection:
        existing=connection.execute("SELECT seq,digest FROM events WHERE host=? AND boot=? AND event_id=?",(record["host"],record["boot"],record["event_id"])).fetchone()
        if existing:
            if existing[1]!=digest:raise ValueError("same event identity changed original content")
            return existing[0]
        cursor=connection.execute("INSERT INTO events(host,boot,event_id,trace,digest,payload) VALUES(?,?,?,?,?,?)",(record["host"],record["boot"],record["event_id"],record["trace"],digest,json.dumps(record,sort_keys=True)))
        return cursor.lastrowid
def timeline(connection,trace):
    received=[json.loads(row[0]) for row in connection.execute("SELECT payload FROM events WHERE trace=? ORDER BY seq",(trace,))]
    same=bool(received) and len({(r["host"],r["boot"]) for r in received})==1
    source=sorted(received,key=lambda r:r["mono_ns"]) if same else None
    return {"received":received,"source_order":source,"elapsed_ns":source[-1]["mono_ns"]-source[0]["mono_ns"] if same else None}
```

原题知识说明：
同时保留带时区墙上时间、单调持续时间或事件序列、主机/进程启动标识及请求ID，记录时间同步异常。跨主机排序应考虑偏差范围，不能仅按格式化时间认定因果；检查日志转发延迟与重复，保留原始时间和接收时间。

